using System;
using System.Collections.Generic;
using UnityEngine;

namespace DD.Prototype.Audio
{
    /// <summary>The five ambience regions (DEC-066 K/D/G/B + centre). Order = bed order.</summary>
    public enum AudioRegion
    {
        Center = 0,
        North = 1,
        East = 2,
        South = 3,
        West = 4,

        /// <summary>Outside every polygon, or no map loaded: the common bed alone carries the scene.</summary>
        None = 5
    }

    /// <summary>
    /// WP-021 · Region polygons for the ambience beds, in Unity XZ, generated by the Editor
    /// tool from the AP-005 placement asset's <c>regions</c> (the same polygons WP-014 tags
    /// instances with). Loaded from <c>Resources/DD_AudioRegionMap</c>; without it the
    /// resolver answers <see cref="AudioRegion.None"/> and only the common bed plays.
    ///
    /// Point-in-polygon per query, five polygons of ~4-12 vertices: a few hundred multiplies,
    /// called a few times a second by the ambience director, never per frame.
    /// </summary>
    [CreateAssetMenu(fileName = "DD_AudioRegionMap", menuName = "DD/Audio/Region Map")]
    public sealed class AudioRegionMap : ScriptableObject
    {
        public const string ResourcePath = "DD_AudioRegionMap";

        [Serializable]
        public sealed class Polygon
        {
            public AudioRegion Region;
            public string SourceId = string.Empty;

            /// <summary>Flattened (x, z) pairs.</summary>
            public float[] XZ = Array.Empty<float>();

            public Vector2 Centroid;
        }

        [SerializeField] private string _sourceVersion = string.Empty;
        [SerializeField] private Polygon[] _polygons = Array.Empty<Polygon>();

        public string SourceVersion => _sourceVersion;
        public IReadOnlyList<Polygon> Polygons => _polygons;

        private static AudioRegionMap s_loaded;
        private static bool s_loadAttempted;

        public static AudioRegionMap Load()
        {
            if (!s_loadAttempted)
            {
                s_loadAttempted = true;
                s_loaded = Resources.Load<AudioRegionMap>(ResourcePath);
            }

            return s_loaded;
        }

        public static void OverrideForTests(AudioRegionMap map, bool clearOnly = false)
        {
            s_loadAttempted = !clearOnly;
            s_loaded = clearOnly ? null : map;
        }

        public void Set(string sourceVersion, List<Polygon> polygons)
        {
            polygons.Sort((a, b) => ((int)a.Region).CompareTo((int)b.Region));
            for (int i = 0; i < polygons.Count; i++)
            {
                polygons[i].Centroid = CentroidOf(polygons[i].XZ);
            }

            _sourceVersion = sourceVersion ?? string.Empty;
            _polygons = polygons.ToArray();
        }

        /// <summary>The region containing the point, else the nearest centroid within <paramref name="snapDistance"/>, else None.</summary>
        public AudioRegion Resolve(Vector3 position, float snapDistance = 6f)
        {
            float px = position.x, pz = position.z;
            for (int i = 0; i < _polygons.Length; i++)
            {
                if (Contains(_polygons[i].XZ, px, pz))
                {
                    return _polygons[i].Region;
                }
            }

            AudioRegion best = AudioRegion.None;
            float bestSq = snapDistance * snapDistance;
            for (int i = 0; i < _polygons.Length; i++)
            {
                float dx = _polygons[i].Centroid.x - px;
                float dz = _polygons[i].Centroid.y - pz;
                float sq = dx * dx + dz * dz;
                if (sq < bestSq)
                {
                    bestSq = sq;
                    best = _polygons[i].Region;
                }
            }

            return best;
        }

        public static bool Contains(float[] xz, float px, float pz)
        {
            int n = xz.Length / 2;
            if (n < 3)
            {
                return false;
            }

            bool inside = false;
            for (int i = 0, j = n - 1; i < n; j = i++)
            {
                float xi = xz[i * 2], zi = xz[i * 2 + 1];
                float xj = xz[j * 2], zj = xz[j * 2 + 1];
                bool crosses = (zi > pz) != (zj > pz);
                if (crosses && px < (xj - xi) * (pz - zi) / (zj - zi + 1e-9f) + xi)
                {
                    inside = !inside;
                }
            }

            return inside;
        }

        public static Vector2 CentroidOf(float[] xz)
        {
            int n = xz.Length / 2;
            if (n == 0)
            {
                return Vector2.zero;
            }

            float sx = 0f, sz = 0f;
            for (int i = 0; i < n; i++)
            {
                sx += xz[i * 2];
                sz += xz[i * 2 + 1];
            }

            return new Vector2(sx / n, sz / n);
        }

        public static AudioRegion Parse(string id)
        {
            switch ((id ?? string.Empty).Trim().ToLowerInvariant())
            {
                case "center":
                case "centre": return AudioRegion.Center;
                case "north": return AudioRegion.North;
                case "east": return AudioRegion.East;
                case "south": return AudioRegion.South;
                case "west": return AudioRegion.West;
                default: return AudioRegion.None;
            }
        }

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetStatics()
        {
            s_loaded = null;
            s_loadAttempted = false;
        }
    }
}
